#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto do_op = [&](int x, int y){
        // x>=1, y>=1, x+y < n
        ops.push_back({x,y});
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
    };

    // Place elements one by one: put value (t+1) at position t
    for(int t=0; t<n-1; t++){
        int pos=-1;
        for(int i=0;i<n;i++) if(p[i]==t+1){pos=i;break;}
        if(pos==t) continue;

        // Step 1: Move element to position 0 if not there
        if(pos > 0 && pos < n-1){
            // x=pos, y=1 => need pos+1<n => pos<n-1 ✓
            // result: [p[n-1]], [p[pos]..p[n-2]], [p[0]..p[pos-1]]
            // element was at pos, now it's at position 1... no.
            // Actually: set y = n-pos, x=1 if possible
            // Move to front: y = n - pos, x can be anything s.t. x+y<n => x < pos
            int y = n - pos; // takes elements from pos..n-1 to front
            int x = max(1, pos > 1 ? 1 : 1);
            if(x + y < n){
                do_op(x, y);
                pos = 0; // element is now at position 0
            }
        }
        if(pos == n-1){
            if(1 + 1 < n){ do_op(1,1); pos=0; /* element at n-1 goes to front */ }
        }
        // Now element should be at position 0, need it at position t
        for(int i=0;i<n;i++) if(p[i]==t+1){pos=i;break;}
        if(pos==t) continue;
        if(pos==0 && t>0 && t<n-1){
            // x = t, y = 1: [p[n-1]], [p[t]..p[n-2]], [p[0]..p[t-1]]
            // p[0] goes to position n-1... no. first x go to end. p[0] at end position n-t
            // Actually: x=1, y=n-t => element at 0 goes to position n-1. Hmm.
            // x = t means first t go to end. We want p[0] at position t.
            // After op(n-t, 1): [p[n-1]], [p[n-t]..p[n-2]], [p[0]..p[n-t-1]]. p[0] at pos n-t.
            do_op(n-t-1, 1); // p[0] moves to position n-(n-t-1)=t+1... let me just search
            for(int i=0;i<n;i++) if(p[i]==t+1){pos=i;break;}
            if(pos!=t && pos>0 && n-pos>=1 && pos<n-1) do_op(pos, n-pos-1>0? 1 : 1);
            // brute force fix
            for(int iter=0;iter<3*n && pos!=t;iter++){
                for(int i=0;i<n;i++) if(p[i]==t+1){pos=i;break;}
                if(pos==t) break;
                int x=max(1,min(pos,(int)(n-2)));
                int y=max(1,min(n-1-x,(int)(n-pos)));
                if(x+y>=n) y=n-1-x;
                if(y<1) {x--;y=1;}
                if(x<1) break;
                do_op(x,y);
            }
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
